import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import type { TraceRow } from './rules';

// Traceability matrix writer (Spec 000, RF-42 / RF-43): docs/traceability.md with one row per
// Spec / RF / TC / test file / status, sorted so the file diffs cleanly between runs.

const NO_TEST_FILE = '—';
const HEADER = [
  '# Traceability Matrix',
  '',
  'Spec → Requirement → Test case → Automated test → Status.',
  'Regenerated by `npm run spec:check -- --write`; do not edit by hand.',
  'Status: `automated` (test exists) · `skipped` (only skipped tests) · `manual` (Automate: N) ·',
  '`missing` (Automate: Y without a test).',
  '',
  '| Spec | RF | Test case | Test file | Status |',
  '|------|----|-----------|-----------|--------|',
];

const rfNumber = (rf: string): number => Number(rf.replace('RF-', ''));

function compareRows(a: TraceRow, b: TraceRow): number {
  return a.spec.localeCompare(b.spec) || rfNumber(a.rf) - rfNumber(b.rf) || a.testCase.localeCompare(b.testCase);
}

export function renderMatrix(rows: TraceRow[]): string {
  const lines = [...rows].sort(compareRows).map((row) => {
    const files = row.testFiles.length === 0 ? NO_TEST_FILE : row.testFiles.join(', ');
    return `| ${row.spec} | ${row.rf} | ${row.testCase} | ${files} | ${row.status} |`;
  });
  return [...HEADER, ...lines, ''].join('\n');
}

/** Writes the matrix; returns the OS error message instead of throwing (RF-43). */
export function writeMatrix(path: string, rows: TraceRow[]): string | undefined {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, renderMatrix(rows));
    return undefined;
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
}
